  | "subscription"
  | "feature_flag";

export interface ActivityEvent extends TenantScoped {
  readonly id: ActivityId;
  readonly action: ActivityAction;
  readonly actorId: UserId | null;
  readonly subjectKind: ActivitySubjectKind;
  readonly subjectId: string;
  readonly projectId: ProjectId | null;
  readonly summary: string;
  readonly metadata: Readonly<Record<string, string | number | boolean | null>>;
  readonly occurredAt: IsoTimestamp;
}

/** Filter for the activity feed page and the audit-log CSV export. */
export interface ActivityFilter {
  readonly action?: readonly ActivityAction[];
  readonly actorId?: UserId;
  readonly projectId?: ProjectId;
  readonly subjectKind?: ActivitySubjectKind;
  readonly since?: IsoTimestamp;
  readonly until?: IsoTimestamp;
}

/** Activity rows grouped by calendar day, as the feed renders them. */
export interface ActivityGroup {
  readonly day: string;
  readonly events: readonly ActivityEvent[];
}
import { index, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns } from "./_shared";

export const activityEvents = sqliteTable(
  "activity_events",
  {
    id: idColumn(),
    ...tenantColumns,
    action: text("action").notNull(),
    actorId: text("actor_id"),
    subjectKind: text("subject_kind", {
      enum: [
        "organization",
        "project",
        "issue",
        "comment",
        "member",
        "subscription",
        "feature_flag",
      ],
    }).notNull(),
    subjectId: text("subject_id").notNull(),
    projectId: text("project_id"),
    summary: text("summary").notNull(),
    /** JSON object of scalar metadata. */
    metadata: text("metadata").notNull().default("{}"),
    occurredAt: text("occurred_at").notNull(),
  },
  (table) => [
    index("activity_org_occurred_idx").on(table.orgId, table.occurredAt),
    index("activity_org_action_idx").on(table.orgId, table.action),
    index("activity_org_subject_idx").on(table.orgId, table.subjectKind, table.subjectId),
  ],
);

export type ActivityEventRow = typeof activityEvents.$inferSelect;
export type NewActivityEventRow = typeof activityEvents.$inferInsert;

